using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.IO;
using System.Diagnostics;
using Aict.Core;
using Microsoft.Win32;
namespace Aict.Beta.Desktop;
internal static class Ui {
    public static StackPanel Layout(Window w,string heading){w.FontFamily=new FontFamily("Microsoft YaHei UI");w.Width=740;w.Height=570;w.MinWidth=650;w.MinHeight=480;w.WindowStartupLocation=WindowStartupLocation.CenterScreen;w.Background=new SolidColorBrush(Color.FromRgb(244,247,251));var panel=new StackPanel{Margin=new Thickness(28)};w.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(new TextBlock{Text=heading,FontSize=24,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,16)});return panel;}
    public static TextBlock Text(Panel p,string text){var t=new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,6,0,12)};p.Children.Add(t);return t;}
    public static Button Button(Panel p,string text,Action action){var b=new Button{Content=text,HorizontalAlignment=HorizontalAlignment.Left,MinWidth=210};b.Click+=(_,_)=>{try{action();}catch(Exception e){MessageBox.Show(e.Message,"专注计划",MessageBoxButton.OK,MessageBoxImage.Information);}};p.Children.Add(b);return b;}
    public static void Open(string exe,string? arg=null){var start=new ProcessStartInfo(exe){UseShellExecute=true};if(arg is not null)start.ArgumentList.Add(arg);Process.Start(start);}
    public static string Browser(string kind){string rel=kind=="Edge"?@"Microsoft\Edge\Application\msedge.exe":@"Google\Chrome\Application\chrome.exe";foreach(string parent in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)}){string exe=Path.Combine(parent,rel);if(File.Exists(exe))return exe;}throw new IOException("未安装这个浏览器。");}
}
internal sealed class SetupWindow:Window {
    public SetupWindow(string? root){
        bool cleaned=Platform.Cleaned(root);Title="专注计划 · 安装向导";var p=Ui.Layout(this,root is null?"欢迎使用专注计划":"继续使用原来的规则");
        Ui.Text(p,root is null?"安装后从桌面“专注计划”打开。初始为空规则，选择并提交后才开始执行。":"启动或修复会使用原数据库，保留原安装模式，不重置规则或已有用量。");
        Ui.Text(p,BuildMode.HostTrial?"默认持续使用：规则按你设置的日程、额度及锁定条件执行，没有统一的30分钟截止时间。安装需要一次管理员确认，独立管理员故障恢复工具保留。":"目前仅安装到 VMware 虚拟机，安装需要管理员确认。");
        var trial=new CheckBox{Content="仅试用30分钟，到期保留并停用规则",Margin=new Thickness(0,8,0,12),Visibility=BuildMode.HostTrial&&(root is null||cleaned)?Visibility.Visible:Visibility.Collapsed};p.Children.Add(trial);
        var feedback=Ui.Text(p,"");var b=new Button{Content=cleaned?"重新安装（新规则，历史保留）":root is null?"安装并开始":"启动 / 修复后台",MinWidth=240,HorizontalAlignment=HorizontalAlignment.Left};p.Children.Add(b);
        b.Click+=async(_,_)=>{b.IsEnabled=false;trial.IsEnabled=false;feedback.Text="正在处理安装与恢复，请稍候…";try{await Platform.Install(root is not null,root,newSession:cleaned,shortTrial:trial.IsChecked==true);string selected=Platform.FindExisting()??throw new IOException("安装未找到有效会话。");await ((App)Application.Current).OpenMainWindow(new BetaConnection(selected));Close();}catch(Exception e){feedback.Text=e.Message;b.IsEnabled=true;trial.IsEnabled=true;}};
        Ui.Button(p,"打开安装诊断位置",()=>Ui.Open("explorer.exe",root??Platform.Package));Ui.Text(p,"浏览器保护首次需要加载本包组件，安装后有图形引导。启用网站规则前请先完成这一步。");
    }
}
internal sealed class RecoveryWindow:Window {
    public RecoveryWindow(string? root){Title="专注计划 · 管理员故障恢复";var p=Ui.Layout(this,"独立的管理员故障恢复");Ui.Text(p,"此工具会绕过正常锁定，撤销本软件的服务、应用策略和浏览器网络保护。仅用于误封或损坏，不是日常关闭限制的按钮。规则与日志保留。");Ui.Text(p,root is null?"没有找到当前用户的安装。":"将恢复当前用户的已有安装。输入“我确认这是故障恢复”，再点击恢复并完成管理员确认。");var phrase=new TextBox();p.Children.Add(phrase);var status=Ui.Text(p,"");var button=new Button{Content="管理员故障恢复",IsEnabled=false,HorizontalAlignment=HorizontalAlignment.Left};p.Children.Add(button);phrase.TextChanged+=(_,_)=>button.IsEnabled=root is not null && phrase.Text=="我确认这是故障恢复";button.Click+=async(_,_)=>{button.IsEnabled=false;try{await Platform.Install(true,root,true);status.Text="已确认恢复完成。规则和诊断数据保留，可以关闭本窗口。";}catch(Exception e){status.Text=e.Message;button.IsEnabled=true;}};}
}
internal sealed class BrowserWindow:Window {
    readonly BetaConnection connection;readonly TextBlock status;
    public BrowserWindow(BetaConnection connection){this.connection=connection;Title="专注计划 · 浏览器保护设置";var p=Ui.Layout(this,"连接 Edge / Chrome 浏览器保护");Ui.Text(p,"1. 打开浏览器扩展页面，开启“开发者模式”。\n2. 点击“加载已解压的扩展程序”，选择下面复制的文件夹。\n3. 返回此处刷新状态，确认组件已连接，再启用网站规则。\n更新后请点击现有组件的“重新加载”；正式商店部署尚未完成。");string folder=Path.Combine(connection.Root??connection.BundleRoot,"Extension");Ui.Text(p,folder);Ui.Button(p,"复制组件文件夹路径",()=>Clipboard.SetText(folder));Ui.Button(p,"打开组件文件夹",()=>Ui.Open("explorer.exe",folder));Ui.Button(p,"打开 Edge 扩展页面",()=>Ui.Open(Ui.Browser("Edge"),"edge://extensions"));Ui.Button(p,"打开 Chrome 扩展页面",()=>Ui.Open(Ui.Browser("Chrome"),"chrome://extensions"));status=Ui.Text(p,"");var refresh=Ui.Button(p,"刷新连接状态",()=>{});refresh.Click+=async(_,_)=>await Refresh();Loaded+=async(_,_)=>await Refresh();Ui.Text(p,"网站规则支持域名、具体页面、* 通配符、白名单、时段、循环和额度。启用网站保护期间，组件失联会限制受管理浏览器联网；关闭界面不影响后台。 ");}
    async Task Refresh(){try{var reply=await connection.CallAsync(new());var web=reply.Status?.Websites;status.Text=web is null?reply.Message:$"已确认组件：{web.ConnectedProfiles} 个配置文件；前台采集：{(web.ForegroundAgentHealthy?"正常":"等待连接")}\n"+(web.Fault??"");}catch(Exception e){status.Text="连接失败："+e.Message;}}
}
internal sealed class StatisticsWindow:Window {
    public StatisticsWindow(BetaConnection connection){Title="专注计划 · 使用统计";Width=920;Height=650;WindowStartupLocation=WindowStartupLocation.CenterOwner;var layout=new DockPanel{Margin=new Thickness(20)};Content=layout;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);layout.Children.Add(top);Ui.Text(top,"前台使用时间约每2秒更新。浏览器应用时间包含网页时间，两者不能相加。缺失观察单独记录为未知时长。");var label=Ui.Text(top,"");var refresh=Ui.Button(top,"刷新统计",()=>{});var grid=new DataGrid{IsReadOnly=true,AutoGenerateColumns=true,CanUserAddRows=false};layout.Children.Add(grid);async Task Load(){try{var reply=await connection.CallAsync(new(){Command=Command.GetActivities});if(!reply.Ok){label.Text=reply.Message;return;}grid.ItemsSource=reply.Activities?.Select(r=>new{日期=r.Day,时区=r.Zone,类别=r.Kind switch{"app"=>"应用","site"=>"网站",_=>"缺口"},名称=r.Name,已知分钟=Math.Round(TimeSpan.FromTicks(r.KnownTicks).TotalMinutes,2),未知分钟=Math.Round(TimeSpan.FromTicks(r.UnknownTicks).TotalMinutes,2)}).ToArray();label.Text=reply.Message;}catch(Exception e){label.Text="统计未能读取："+e.Message;}}refresh.Click+=async(_,_)=>await Load();Loaded+=async(_,_)=>await Load();}
}
internal sealed class DiagnosticsWindow:Window {
    public DiagnosticsWindow(BetaConnection connection){Title="专注计划 · 诊断与卸载";var p=Ui.Layout(this,"诊断与管理");var feedback=Ui.Text(p,"规则修改和正常卸载都必须遵守当前锁定和等待条件。关闭界面不会停止后台。 ");
        var export=Ui.Button(p,"导出规则、用量和日志",()=>{});export.Click+=async(_,_)=>{try{var picker=new OpenFolderDialog{Title="选择导出位置"};if(picker.ShowDialog(this)!=true)return;string folder=Path.Combine(picker.FolderName,"aict-beta-"+DateTimeOffset.UtcNow.ToString("yyyyMMddTHHmmssfffZ"));Directory.CreateDirectory(folder);foreach(var pair in new[]{(Command.ExportJson,"rules-and-usage.json"),(Command.ExportCsv,"quota-usage.csv"),(Command.ExportActivityCsv,"application-site-usage.csv")})try{var r=await connection.CallAsync(new(){Command=pair.Item1});File.WriteAllText(Path.Combine(folder,pair.Item2),r.ExportText??PolicyJson.Serialize(r),new System.Text.UTF8Encoding(true));}catch(Exception e){File.WriteAllText(Path.Combine(folder,pair.Item2+".error.txt"),e.Message);}
            if(connection.Root is {} root){var files=Directory.EnumerateFiles(Path.Combine(root,"state"),"*",SearchOption.AllDirectories).Where(f=>f.EndsWith(".json",StringComparison.OrdinalIgnoreCase)||f.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase));foreach(string src in files){var info=new FileInfo(src);if((info.Attributes&FileAttributes.ReparsePoint)!=0 || info.Length>64*1024*1024)continue;string dest=Path.Combine(folder,"state",Path.GetRelativePath(Path.Combine(root,"state"),src));Directory.CreateDirectory(Path.GetDirectoryName(dest)!);using var input=new FileStream(src,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);using var output=File.Create(dest);await input.CopyToAsync(output);}}
            if(connection.Root is {} installation){string id=Path.GetFileName(installation)[10..];string agentLog=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AICT","beta-agent-"+id+".log");foreach(string suffix in new[]{"",".previous"})if(File.Exists(agentLog+suffix)){var info=new FileInfo(agentLog+suffix);if(info.Length<2097152 && (info.Attributes&FileAttributes.ReparsePoint)==0)File.Copy(agentLog+suffix,Path.Combine(folder,"agent.log"+suffix));}}
            var hashes=Directory.GetFiles(folder,"*",SearchOption.AllDirectories).Select(f=>Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(f)))+"  "+Path.GetRelativePath(folder,f).Replace('\\','/')).ToArray();File.WriteAllLines(Path.Combine(folder,"SHA256SUMS.txt"),hashes);feedback.Text="已导出："+folder;Ui.Open("explorer.exe",folder);
        }catch(Exception e){feedback.Text="导出未完成："+e.Message;}};
        var repair=Ui.Button(p,"启动 / 修复后台（保留规则）",()=>{});repair.Click+=async(_,_)=>{try{if(connection.Root is null)return;await Platform.Install(true,connection.Root);feedback.Text="后台已尝试恢复，请关闭此窗口查看状态。";}catch(Exception e){feedback.Text=e.Message;}};
        var uninstall=Ui.Button(p,"申请正常卸载",()=>{});uninstall.Click+=async(_,_)=>{if(MessageBox.Show(this,"提交卸载申请？后台会按当前延迟和锁定条件决定何时生效；规则和日志保留。","卸载申请",MessageBoxButton.OKCancel)!=MessageBoxResult.OK)return;try{var s=await connection.CallAsync(new());var r=await connection.CallAsync(new(){Command=Command.RequestUninstall,EditToken=s.Status?.EditToken});feedback.Text=r.Message;}catch(Exception e){feedback.Text=e.Message;}};
        Ui.Text(p,"高级故障恢复：仅用于误封或损坏。安装目录中单独提供“管理员恢复工具.exe”，需要管理员确认及恢复短语；它会解除本软件的限制。正常使用无需运行它。");Ui.Button(p,"打开安装目录",()=>Ui.Open("explorer.exe",connection.Root??connection.BundleRoot));
    }
}
